<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { shortDramaApi, type DramaShot, type Storyboard, type StoryboardCandidate, type StoryboardScene, type WorldOverview } from '@/api/modules'
import AssetPicker from '@/v2/components/AssetPicker.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import type { ResourceItem } from '@/v2/features/assets/model'
import type { TaskOutput } from '@/v2/features/tasks/model'

type ViewMode='cards'|'table'|'board';type MediaField='first_frame_resource_id'|'last_frame_resource_id'|'pose_resource_id'|'reference_video_resource_id'|'reference_audio_resource_id'|'reference_resource_ids'
const route=useRoute();const router=useRouter();const projectId=computed(()=>Number(route.params.id));const data=ref<Storyboard|null>(null);const world=ref<WorldOverview>({characters:[],locations:[],props:[],relationships:[]})
const loading=ref(true);const working=ref(false);const error=ref('');const notice=ref('');const view=ref<ViewMode>('cards');const episodeFilter=ref<number|null>(null);const sceneFilter=ref<number|null>(null);const statusFilter=ref('');const characterFilter=ref<number|null>(null)
const selectedSceneId=ref<number|null>(null);const selectedShotId=ref<number|null>(null);const selected=ref(new Set<number>());const candidate=ref<StoryboardCandidate|null>(null);const candidateMode=ref<'replace_drafts'|'append'>('replace_drafts');const draft=ref<DramaShot|null>(null);const dirty=ref(false)
const picker=ref(false);const pickerType=ref<'image'|'video'|'audio'>('image');const mediaField=ref<MediaField>('first_frame_resource_id');const selectedMedia=ref(new Map<number,ResourceItem>());const preview=ref<TaskOutput|null>(null);const dragged=ref<number|null>(null)
const allScenes=computed(()=>data.value?.episodes.flatMap(ep=>ep.scenes.map(scene=>({episode:ep.episode,scene})))||[])
const selectedScene=computed(()=>allScenes.value.find(item=>item.scene.scene.id===selectedSceneId.value)?.scene||null)
const visibleScenes=computed(()=>allScenes.value.filter(item=>(!episodeFilter.value||item.episode.id===episodeFilter.value)&&(!sceneFilter.value||item.scene.scene.id===sceneFilter.value)))
const visibleShots=computed(()=>visibleScenes.value.flatMap(item=>item.scene.shots.map(shot=>({episode:item.episode,scene:item.scene,shot}))).filter(item=>(!statusFilter.value||item.shot.status===statusFilter.value)&&(!characterFilter.value||item.shot.character_ids.includes(characterFilter.value))))
const shotDefaults=(scene:StoryboardScene)=>({purpose:'',visual_description:'',action:'',expression:'',dialogue:'',timeline_storyboard:'',video_prompt:'',negative_prompt:'',continuity:'',character_ids:[...(scene.scene.character_ids||[])],location_id:scene.scene.location_id,prop_ids:[],mood:'',shot_size:'中景',camera_angle:'平视',camera_movement:'固定',composition:'主体居中',transition:'切',duration:3,first_frame_resource_id:null,last_frame_resource_id:null,pose_resource_id:null,reference_video_resource_id:null,reference_audio_resource_id:null,reference_resource_ids:[],status:'draft',production_settings:{}})
function message(event:any,fallback:string){return event.response?.data?.detail||event.response?.data?.message||fallback}
async function load(){loading.value=true;error.value='';try{const [board,setting]=await Promise.all([shortDramaApi.storyboard(projectId.value),shortDramaApi.world(projectId.value)]);data.value=board;world.value=setting;if(!selectedSceneId.value)selectedSceneId.value=allScenes.value[0]?.scene.scene.id||null;if(selectedShotId.value){const current=visibleShots.value.find(item=>item.shot.id===selectedShotId.value)?.shot;if(current){draft.value=structuredClone(current);dirty.value=false}else{selectedShotId.value=null;draft.value=null}}}catch(event:any){error.value=message(event,'分镜工作台加载失败')}finally{loading.value=false}}
function chooseScene(id:number){selectedSceneId.value=id;sceneFilter.value=id;candidate.value=null;selectedShotId.value=null;draft.value=null}
function editShot(shot:DramaShot){selectedShotId.value=shot.id;selectedSceneId.value=shot.scene_id;draft.value=structuredClone(shot);dirty.value=false}
async function extract(){if(!selectedSceneId.value)return;working.value=true;try{candidate.value=await shortDramaApi.createShotCandidate(projectId.value,selectedSceneId.value);notice.value='拆镜建议只用于预览，确认前不会修改现有镜头。'}catch(event:any){error.value=message(event,'拆镜失败')}finally{working.value=false}}
async function confirm(){if(!candidate.value)return;working.value=true;try{await shortDramaApi.confirmShotCandidate(projectId.value,candidate.value.id,candidateMode.value);candidate.value=null;notice.value=candidateMode.value==='append'?'建议镜头已追加':'草稿镜头已替换，已确认镜头被保留';await load()}catch(event:any){error.value=message(event,'确认失败')}finally{working.value=false}}
async function createShot(){if(!selectedScene.value)return;working.value=true;try{const item=await shortDramaApi.createShot(projectId.value,selectedScene.value.scene.id,shotDefaults(selectedScene.value));await load();editShot(item)}catch(event:any){error.value=message(event,'新建镜头失败')}finally{working.value=false}}
function body(){if(!draft.value)return{};const keys=['purpose','visual_description','action','expression','dialogue','timeline_storyboard','video_prompt','negative_prompt','continuity','character_ids','location_id','prop_ids','mood','shot_size','camera_angle','camera_movement','composition','transition','duration','first_frame_resource_id','last_frame_resource_id','pose_resource_id','reference_video_resource_id','reference_audio_resource_id','reference_resource_ids','status','production_settings'];return Object.fromEntries(keys.map(key=>[key,(draft.value as any)[key]]))}
async function save(){if(!draft.value)return;working.value=true;try{const item=await shortDramaApi.updateShot(projectId.value,draft.value.id,{...body(),lock_version:draft.value.lock_version});notice.value='镜头已保存';dirty.value=false;await load();editShot(item)}catch(event:any){error.value=message(event,'镜头保存失败')}finally{working.value=false}}
async function copy(shot:DramaShot){await shortDramaApi.copyShot(projectId.value,shot.id);await load()}
async function split(shot:DramaShot){await shortDramaApi.splitShot(projectId.value,shot.id,.5);await load()}
async function remove(shot:DramaShot){if(!window.confirm(`删除镜头 ${shot.shot_no}？`))return;await shortDramaApi.deleteShot(projectId.value,shot.id);selectedShotId.value=null;draft.value=null;await load()}
function toggle(id:number){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
async function merge(){if(selected.value.size<2)return;await shortDramaApi.mergeShots(projectId.value,[...selected.value]);selected.value=new Set();await load()}
async function bulk(status?:'draft'|'ready'){if(!selected.value.size)return;const durationText=status?null:window.prompt('统一时长（秒）','3');if(!status&&!durationText)return;await shortDramaApi.bulkPatchShots(projectId.value,{shot_ids:[...selected.value],...(status?{status}:{duration:Number(durationText)})});selected.value=new Set();await load()}
async function drop(target:number){if(!dragged.value||dragged.value===target||!selectedScene.value)return;const ids=selectedScene.value.shots.map(item=>item.id);const from=ids.indexOf(dragged.value),to=ids.indexOf(target);if(from<0||to<0)return;ids.splice(to,0,ids.splice(from,1)[0]);await shortDramaApi.reorderShots(projectId.value,selectedScene.value.scene.id,ids);dragged.value=null;await load()}
function openPicker(field:MediaField,type:'image'|'video'|'audio'){mediaField.value=field;pickerType.value=type;picker.value=true}
function chooseMedia(items:ResourceItem[]){if(!draft.value)return;for(const item of items)selectedMedia.value.set(item.id,item);if(mediaField.value==='reference_resource_ids')draft.value.reference_resource_ids=[...new Set([...draft.value.reference_resource_ids,...items.map(item=>item.id)])];else(draft.value as any)[mediaField.value]=items[0]?.id||null;selectedMedia.value=new Map(selectedMedia.value);dirty.value=true}
function openPreview(id:number|null,type:'image'|'video'|'audio'){if(!id)return;const item=selectedMedia.value.get(id);preview.value={id,filename:item?.filename||`素材 #${id}`,media_type:type,mime:item?.mime||`${type}/*`}}
function charName(id:number){return world.value.characters.find(item=>item.id===id)?.name||`#${id}`}
function locationName(id:number|null){return world.value.locations.find(item=>item.id===id)?.name||'未关联地点'}
onMounted(load)
</script>

<template>
  <div class="v2-page storyboard-page">
    <header class="page-head"><div><button class="back" @click="router.push(`/v2/drama/projects/${projectId}`)">← 项目概览</button><h1>分镜工作台</h1><p v-if="data">{{ data.project.name }} · {{ data.total_shots }} 镜头 / {{ data.ready_shots }} 已确认 / {{ data.total_duration.toFixed(1) }} 秒</p></div><div class="head-actions"><V2Button variant="ghost" @click="router.push(`/v2/drama/projects/${projectId}/world`)">角色与世界</V2Button><V2Button variant="ghost" @click="router.push(`/v2/drama/projects/${projectId}/production`)">镜头生产</V2Button><V2Button variant="ghost" @click="extract">智能拆镜</V2Button><V2Button variant="primary" @click="createShot">＋ 新建镜头</V2Button></div></header>
    <p v-if="error" class="banner error">{{ error }}</p><p v-if="notice" class="banner notice">{{ notice }}</p>
    <section v-if="candidate" class="candidate"><div><StatusBadge tone="warning">拆镜建议待确认</StatusBadge><h2>{{ candidate.payload.shots.length }} 个建议镜头</h2><p>来源剧本版本 #{{ candidate.story_version_id }} · 目标 {{ candidate.payload.target_duration }} 秒</p><span v-for="warning in candidate.validation_warnings" :key="warning.code">{{ warning.message }}</span></div><div class="candidate-shots"><article v-for="(shot,index) in candidate.payload.shots" :key="index"><b>{{ index+1 }}</b><span>{{ shot.shot_size }} · {{ shot.duration }}s</span><p>{{ shot.visual_description }}</p></article></div><div class="confirm-actions"><select v-model="candidateMode"><option value="replace_drafts">替换草稿，保留已确认</option><option value="append">追加到现有镜头</option></select><V2Button variant="primary" :disabled="working" @click="confirm">确认写入</V2Button><V2Button variant="ghost" @click="candidate=null">取消</V2Button></div></section>
    <div class="toolbar"><div class="view-switch"><button v-for="item in [{k:'cards',n:'卡片'},{k:'table',n:'表格'},{k:'board',n:'故事板'}]" :key="item.k" :class="{active:view===item.k}" @click="view=item.k as ViewMode">{{ item.n }}</button></div><select v-model="episodeFilter"><option :value="null">全部分集</option><option v-for="item in data?.episodes" :key="item.episode.id" :value="item.episode.id">EP {{ item.episode.number }} {{ item.episode.title }}</option></select><select v-model="sceneFilter"><option :value="null">全部场景</option><option v-for="item in allScenes" :key="item.scene.scene.id" :value="item.scene.scene.id">{{ item.scene.scene.scene_no }} {{ item.scene.scene.heading }}</option></select><select v-model="statusFilter"><option value="">全部状态</option><option value="draft">草稿</option><option value="ready">可生成</option></select><select v-model="characterFilter"><option :value="null">全部角色</option><option v-for="item in world.characters" :key="item.id" :value="item.id">{{ item.name }}</option></select><div v-if="selected.size" class="batch"><b>已选 {{ selected.size }}</b><button @click="bulk('ready')">设为可生成</button><button @click="bulk()">统一时长</button><button @click="merge">合并</button></div></div>
    <main v-if="data" class="workspace"><aside class="tree"><section v-for="episode in data.episodes" :key="episode.episode.id"><header>EP {{ episode.episode.number }} · {{ episode.episode.title }}</header><button v-for="item in episode.scenes" :key="item.scene.id" :class="{active:selectedSceneId===item.scene.id}" @click="chooseScene(item.scene.id)"><span>{{ item.scene.scene_no }}</span><b>{{ item.scene.heading }}</b><small>{{ item.shots.length }} 镜 · {{ item.shot_duration }}/{{ item.target_duration }}s</small><i :class="{warn:Math.abs(item.duration_delta)>.1}">{{ item.duration_delta>0?'+':'' }}{{ item.duration_delta.toFixed(1) }}</i></button></section></aside>
      <section class="content">
        <div v-if="loading" class="empty">正在加载分镜…</div><div v-else-if="!visibleShots.length" class="empty"><b>当前没有镜头</b><span>选择场景后智能拆镜，或手工新建镜头。</span></div>
        <div v-else-if="view==='cards'" class="cards"><article v-for="item in visibleShots" :key="item.shot.id" class="shot-card" :class="{active:selectedShotId===item.shot.id}" draggable="true" @dragstart="dragged=item.shot.id" @dragover.prevent @drop.prevent="drop(item.shot.id)" @click="editShot(item.shot)"><button class="check" @click.stop="toggle(item.shot.id)">{{ selected.has(item.shot.id)?'✓':'○' }}</button><div class="frame"><span>{{ item.shot.first_frame_resource_id?'已绑定首帧':'2:3 分镜预览' }}</span><b>{{ item.shot.shot_no }}</b></div><div class="copy"><header><strong>{{ item.episode.number }}-{{ item.scene.scene.scene_no }}-{{ item.shot.shot_no }}</strong><StatusBadge :tone="item.shot.status==='ready'?'success':'neutral'">{{ item.shot.status==='ready'?'可生成':'草稿' }}</StatusBadge></header><p>{{ item.shot.visual_description||'未填写画面描述' }}</p><div class="tags"><span>{{ item.shot.shot_size }}</span><span>{{ item.shot.camera_movement }}</span><span>{{ item.shot.duration }}s</span><span v-if="item.shot.timeline_storyboard">时间轴✓</span><span v-if="item.shot.video_prompt">视频词✓</span><span v-if="item.shot.continuity">连续性✓</span></div><small>{{ item.shot.character_ids.map(charName).join('、')||'无角色' }} · {{ locationName(item.shot.location_id) }}</small><footer><button @click.stop="copy(item.shot)">复制</button><button @click.stop="split(item.shot)">拆分</button><button @click.stop="remove(item.shot)">删除</button></footer></div></article></div>
        <div v-else-if="view==='table'" class="table-wrap"><table><thead><tr><th></th><th>镜号</th><th>画面</th><th>角色 / 地点</th><th>景别</th><th>运镜</th><th>时长</th><th>状态</th></tr></thead><tbody><tr v-for="item in visibleShots" :key="item.shot.id" @click="editShot(item.shot)"><td><button @click.stop="toggle(item.shot.id)">{{ selected.has(item.shot.id)?'✓':'○' }}</button></td><td>{{ item.episode.number }}-{{ item.scene.scene.scene_no }}-{{ item.shot.shot_no }}</td><td>{{ item.shot.visual_description }}</td><td>{{ item.shot.character_ids.map(charName).join('、') }} / {{ locationName(item.shot.location_id) }}</td><td>{{ item.shot.shot_size }}</td><td>{{ item.shot.camera_movement }}</td><td>{{ item.shot.duration }}s</td><td>{{ item.shot.status==='ready'?'可生成':'草稿' }}</td></tr></tbody></table></div>
        <div v-else class="storyboard"><article v-for="item in visibleShots" :key="item.shot.id" @click="editShot(item.shot)"><div><b>{{ item.shot.shot_no }}</b><span>2:3</span></div><p>{{ item.shot.visual_description }}</p><footer><span>{{ item.shot.shot_size }}</span><strong>{{ item.shot.duration }}s</strong></footer></article></div>
      </section>
      <aside class="editor"><div v-if="!draft" class="empty">选择镜头查看属性</div><template v-else><header><div><small>镜头 {{ draft.shot_no }}</small><h2>{{ draft.purpose||'镜头属性' }}</h2></div><StatusBadge :tone="dirty?'warning':draft.status==='ready'?'success':'neutral'">{{ dirty?'未保存':draft.status==='ready'?'可生成':'草稿' }}</StatusBadge></header><label>叙事目的<input v-model="draft.purpose" @input="dirty=true"></label><label>画面描述<textarea v-model="draft.visual_description" rows="4" @input="dirty=true"></textarea></label><div class="two"><label>动作<textarea v-model="draft.action" rows="2" @input="dirty=true"></textarea></label><label>表情<input v-model="draft.expression" @input="dirty=true"></label></div><label>对白 / 旁白<textarea v-model="draft.dialogue" rows="3" @input="dirty=true"></textarea></label>
          <label>时间轴分镜 <small>一个 Shot 可包含多个内部镜头，统一保存在此字段</small><textarea v-model="draft.timeline_storyboard" rows="8" @input="dirty=true"></textarea></label>
          <label>连续性入口 / 出口<textarea v-model="draft.continuity" rows="4" @input="dirty=true"></textarea></label>
          <details class="generation-copy" :open="!!draft.video_prompt"><summary>生成提示词</summary><label>导演视频提示词<textarea v-model="draft.video_prompt" rows="8" @input="dirty=true"></textarea></label><label>负面提示词<textarea v-model="draft.negative_prompt" rows="4" @input="dirty=true"></textarea></label></details>
          <fieldset><legend>角色</legend><label v-for="item in world.characters" :key="item.id"><input v-model="draft.character_ids" type="checkbox" :value="item.id" @change="dirty=true">{{ item.name }}</label></fieldset><div class="two"><label>地点<select v-model="draft.location_id" @change="dirty=true"><option :value="null">不关联</option><option v-for="item in world.locations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>情绪<input v-model="draft.mood" @input="dirty=true"></label><label>景别<select v-model="draft.shot_size" @change="dirty=true"><option v-for="item in ['远景','全景','中景','近景','特写']" :key="item">{{ item }}</option></select></label><label>机位<select v-model="draft.camera_angle" @change="dirty=true"><option v-for="item in ['平视','俯拍','仰拍','侧面','主观']" :key="item">{{ item }}</option></select></label><label>运镜<input v-model="draft.camera_movement" @input="dirty=true"></label><label>构图<input v-model="draft.composition" @input="dirty=true"></label><label>转场<input v-model="draft.transition" @input="dirty=true"></label><label>时长（秒，最多 15 秒）<input v-model.number="draft.duration" type="number" min=".1" max="15" step=".1" @input="dirty=true"></label></div><section class="media"><b>镜头素材</b><div><button @click="openPicker('first_frame_resource_id','image')">首帧 #{{ draft.first_frame_resource_id||'—' }}</button><button v-if="draft.first_frame_resource_id" @click="openPreview(draft.first_frame_resource_id,'image')">预览</button><button @click="openPicker('last_frame_resource_id','image')">尾帧 #{{ draft.last_frame_resource_id||'—' }}</button><button @click="openPicker('pose_resource_id','image')">姿态图 #{{ draft.pose_resource_id||'—' }}</button><button @click="openPicker('reference_video_resource_id','video')">参考视频 #{{ draft.reference_video_resource_id||'—' }}</button><button v-if="draft.reference_video_resource_id" @click="openPreview(draft.reference_video_resource_id,'video')">播放</button><button @click="openPicker('reference_audio_resource_id','audio')">参考音频 #{{ draft.reference_audio_resource_id||'—' }}</button></div></section><label>状态<select v-model="draft.status" @change="dirty=true"><option value="draft">草稿</option><option value="ready">可生成</option></select></label><V2Button variant="primary" :disabled="working||!dirty" @click="save">{{ working?'保存中…':'保存镜头' }}</V2Button></template></aside>
    </main>
    <AssetPicker :open="picker" :media-type="pickerType" :multiple="mediaField==='reference_resource_ids'" @close="picker=false" @select="chooseMedia"/><MediaViewer :open="!!preview" :output="preview" @close="preview=null"/>
  </div>
</template>

<style scoped>
